/// <summary>
/// MPJ_34596_TransferOrderFinalisation, Constructs the reference identities used to populate the <c>MetTransferOrderFinalisationWorkspace</c> form.
/// </summary>
public  class MetTransferOrderShipWorkbenchProcessor
{
    MetTransferOrderShipWorkbenchTmp           MetTransferOrderShipWorkbenchTmp;
    MetTransferOrderShipWorkbenchExtractFilter MetTransferOrderShipWorkbenchExtractFilter;
    InventTransferTable                        inventTransferTable;
    METInventTransferTableExt                  metInventTransferTableExt;
    InventTransferLine                         inventTransferLine;
  
    InventLocationId                        fromWarehouse;
    InventLocationId                        toWarehouse;
    METRoute                                route;
    InventTransferShipDate                  fromShipDate,toShipDate;
    WMSPickingRoute                         wmsPickingRoute;
    WMSOrderTrans                           wmsOrderTrans;
    

  

}

Method.Source:
/// <summary>
/// set or get <c>MetTransferOrderShipWorkbenchExtractFilter</c> class instance.
/// </summary>
/// <param name = "_MetTransferOrderShipWorkbenchExtractFilter"><c>MetTransferOrderShipWorkbenchExtractFilter</c> class instance.</param>
/// <returns><c>MetTransferOrderShipWorkbenchExtractFilter</c> class instance</returns>
public MetTransferOrderShipWorkbenchExtractFilter parmMetTransferOrderShipWorkbenchExtractFilter(
    MetTransferOrderShipWorkbenchExtractFilter _MetTransferOrderShipWorkbenchExtractFilter = MetTransferOrderShipWorkbenchExtractFilter)
{
    MetTransferOrderShipWorkbenchExtractFilter = _MetTransferOrderShipWorkbenchExtractFilter;
    return MetTransferOrderShipWorkbenchExtractFilter;
}

    /// <summary>
    /// set or get <c>MetTransferOrderShipWorkbenchTmp</c> table instance.
    /// </summary>
    /// <param name = "_MetTransferOrderShipWorkbenchTmp"><c>MetTransferOrderShipWorkbenchTmp</c> table instance</param>
    /// <returns><c>MetTransferOrderShipWorkbenchTmp</c> table instance</returns>
    public MetTransferOrderShipWorkbenchTmp parmMetTransferOrderShipWorkbenchTmp(
        MetTransferOrderShipWorkbenchTmp _MetTransferOrderShipWorkbenchTmp = MetTransferOrderShipWorkbenchTmp)
    {
        MetTransferOrderShipWorkbenchTmp.linkPhysicalTableInstance(_MetTransferOrderShipWorkbenchTmp);

        return MetTransferOrderShipWorkbenchTmp;
    }

    /// <summary>
    /// Extracts all the orders by filters.
    /// </summary>
    public void insertOrders()
    {
        insert_recordset MetTransferOrderShipWorkbenchTmp(TransferId)
            select TransferId from inventTransferTable
             where inventTransferTable.TransferStatus == InventTransferStatus::Created &&
                 (!fromWarehouse  || inventTransferTable.InventLocationIdFrom == fromWarehouse)&&
                 (!toWarehouse  || inventTransferTable.InventLocationIdTo == toWarehouse) &&
                 ((!fromshipdate || inventTransferTable.ShipDate >=  fromShipDate) &&
                    (!toShipDate || inventTransferTable.ShipDate <=  toShipDate))
              join wmsPickingRoute where wmsPickingRoute.transRefId == inventTransferTable.TransferId
              join wmsOrderTrans  where wmsOrderTrans.routeId == wmsPickingRoute.pickingRouteID &&
                                    wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Complete
              outer join metInventTransferTableExt
                where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
                //&& metInventTransferTableExt.OrderExtractStatus != METOrderExtractStatus::Extracted
                && (!route  || metInventTransferTableExt.Route == route);


    }

    /// <summary>
    /// Constructs the transfer order finalisation extract screen.
    /// </summary>
    /// <param name="_MetTransferOrderShipWorkbenchTmp">
    /// The <c>MetTransferOrderShipWorkbenchTmp</c> instance.
    /// </param>
    /// <param name="_MetTransferOrderShipWorkbenchExtractFilter">
    /// An instance of <c>MetTransferOrderShipWorkbenchExtractFilter</c> to filter the order onTO workbench form screen form.
    /// </param>
    /// <returns>MetTransferOrderShipWorkbenchProcessor class instance.</returns>
    public static MetTransferOrderShipWorkbenchProcessor construct(
        MetTransferOrderShipWorkbenchTmp                _MetTransferOrderShipWorkbenchTmp,
        MetTransferOrderShipWorkbenchExtractFilter         _MetTransferOrderShipWorkbenchExtractFilter)
    {
        MetTransferOrderShipWorkbenchProcessor   MetTransferOrderShipWorkbenchProcessor;

        MetTransferOrderShipWorkbenchProcessor = new MetTransferOrderShipWorkbenchProcessor();

        MetTransferOrderShipWorkbenchProcessor.populateMetTransferOrderShipWorkbench(_MetTransferOrderShipWorkbenchTmp, _MetTransferOrderShipWorkbenchExtractFilter);

        return MetTransferOrderShipWorkbenchProcessor;
    }

/// <summary>
/// Initialise parameters.
/// </summary>
protected void initParams()
{
    fromWarehouse   = MetTransferOrderShipWorkbenchExtractFilter.parmFromWarehouse();
    toWarehouse     = MetTransferOrderShipWorkbenchExtractFilter.parmToWarehouse();
    route           = MetTransferOrderShipWorkbenchExtractFilter.parmRoute();
    fromShipDate    = MetTransferOrderShipWorkbenchExtractFilter.parmFromShipDate();
    toShipDate      = MetTransferOrderShipWorkbenchExtractFilter.parmToShipDate();
   
}

    /// <summary>
    /// Populates <c>MetTransferOrderShipWorkbenchTmp</c> table for the grid on the order extract screen form.
    /// </summary>
    /// <param name="_MetTransferOrderShipWorkbenchTmp">
    /// The <c>MetTransferOrderShipWorkbenchTmp</c> instance.
    /// </param>
    /// <param name="_MetTransferOrderShipWorkbenchExtractFilter">
    /// An instance of <c>MetTransferOrderShipWorkbenchExtractFilter</c> to filter the order extract screen form.
    /// </param>
    public void populateMetTransferOrderShipWorkbench(MetTransferOrderShipWorkbenchTmp                _MetTransferOrderShipWorkbenchTmp,
                                            MetTransferOrderShipWorkbenchExtractFilter         _MetTransferOrderShipWorkbenchExtractFilter)
    {
        MetTransferOrderShipWorkbenchProcessor           MetTransferOrderShipWorkbenchProcessor;

        MetTransferOrderShipWorkbenchProcessor = new MetTransferOrderShipWorkbenchProcessor();

        MetTransferOrderShipWorkbenchProcessor.parmMetTransferOrderShipWorkbenchExtractFilter(_MetTransferOrderShipWorkbenchExtractFilter);
        MetTransferOrderShipWorkbenchProcessor.parmMetTransferOrderShipWorkbenchTmp(_MetTransferOrderShipWorkbenchTmp);
        MetTransferOrderShipWorkbenchProcessor.initParams();
        MetTransferOrderShipWorkbenchProcessor.insertOrders();
    }
